<template>
  <view :class="['identity-result', { rejected: rejected }]"><jk-page-nav :title="rejected ? '审核拒绝' : '审核通过'"></jk-page-nav>
    <view v-if="application.id" class="result-head"><view class="result-icon">{{ rejected ? '×' : '✓' }}</view><view class="result-title">{{ rejected ? '审核未通过' : '审核通过' }}</view><view class="result-desc">{{ rejected ? '很遗憾，您的业务身份申请未通过，请根据原因修改后重新提交。' : '感谢您的耐心等待，您的业务身份已生效，可正常使用相关服务。' }}</view></view>
    <view v-if="rejected" class="reason-card"><view class="card-title">拒绝原因</view><view>{{ application.rejectReason || '审核未通过，请联系平台客服了解详情。' }}</view></view>
    <view v-else class="info-card"><view class="info-row"><text>身份类型</text><strong>{{ application.applyRoleName }}</strong></view><view class="info-row"><text>所属区域</text><strong>{{ application.regionName || application.regionCode || '-' }}</strong></view><view class="info-row"><text>生效时间</text><strong>{{ formatTime(application.effectiveTime) }}</strong></view><view class="info-row"><text>有效期</text><strong>长期有效</strong></view></view>
    <view v-if="rejected" class="button-group"><button class="primary-btn" @click="reapply">重新申请</button><button class="outline-btn" @click="viewList">查看申请记录</button></view>
    <view v-else><button class="primary-btn" @click="goStatus">进入业务中心</button><button class="text-btn" @click="goStatus">查看身份详情</button></view>
  </view>
</template>
<script>
import { getJkIdentityApplyDetail, getJkIdentityApplyList } from '@/api/jk.js'; import JkPageNav from '@/components/jk/jk-page-nav.vue';
export default {components:{JkPageNav},data(){return{application:{}};},computed:{rejected(){return this.application.auditStatus==='REJECTED';}},onLoad(q){this.id=q.id;this.load();},methods:{load(){getJkIdentityApplyDetail(this.id).then(res=>{this.application=(res.data||res||{}).application||{};}).catch(()=>this.loadFromList());},loadFromList(){getJkIdentityApplyList({page:1,limit:50}).then(res=>{const data=res.data||res||{};const rows=Array.isArray(data)?data:(data.list||data.records||[]);this.application=rows.filter(item=>String(item.id)===String(this.id))[0]||{};if(!this.application.id)this.$util.Tips({title:'申请记录不存在'});}).catch(err=>this.$util.Tips({title:err||'审核结果加载失败'}));},formatTime(v){return v?String(v).replace('T',' ').slice(0,16):'-';},reapply(){uni.redirectTo({url:'/pages/jk/identity/select'});},viewList(){uni.redirectTo({url:'/pages/jk/identity/applyList'});},goStatus(){uni.redirectTo({url:'/pages/jk/identity/status'});}}};
</script>
<style lang="scss">
.identity-result{min-height:100vh;padding:0 34rpx 80rpx;background:radial-gradient(circle at 50% 18%,#e3fff7,#fff 38%);box-sizing:border-box}.result-head{padding:82rpx 18rpx 52rpx;text-align:center}.result-icon{width:170rpx;height:170rpx;margin:0 auto 42rpx;border:20rpx solid #dff9f2;border-radius:50%;background:#08c19f;color:#fff;line-height:170rpx;font-size:112rpx;box-shadow:0 12rpx 34rpx rgba(8,190,155,.22)}.result-title{margin-bottom:22rpx;color:#202633;font-size:52rpx;font-weight:700}.result-desc{color:#727c8c;font-size:29rpx;line-height:1.8}.info-card,.reason-card{padding:0 30rpx;border-radius:24rpx;background:#fff;box-shadow:0 8rpx 28rpx rgba(33,70,61,.08)}.info-row{display:flex;justify-content:space-between;align-items:center;min-height:108rpx;border-bottom:1rpx solid #edf0f2}.info-row:last-child{border:0}.info-row text{color:#77818f;font-size:28rpx}.info-row strong{color:#202633;font-size:30rpx}.primary-btn,.outline-btn{height:94rpx;margin-top:48rpx;border-radius:47rpx;background:#08b996;color:#fff;line-height:94rpx;font-size:34rpx;font-weight:700}.text-btn{margin-top:24rpx;border:0;background:transparent;color:#08ae8d;font-size:31rpx}.rejected{background:radial-gradient(circle at 50% 18%,#fff0ee,#fff 40%)}.rejected .result-icon{border-color:#ffe0dd;background:#ff625a}.reason-card{padding:32rpx;background:#fff7f5;color:#5f4a50;font-size:29rpx;line-height:1.8}.card-title{margin-bottom:18rpx;padding-left:16rpx;border-left:7rpx solid #ff625a;color:#29303a;font-size:34rpx;font-weight:700}.button-group{display:flex;gap:20rpx}.button-group button{flex:1}.button-group .primary-btn{background:#ff625a}.outline-btn{border:2rpx solid #ff625a;background:#fff;color:#ff625a}
</style>
